{"action_type": "exec", "command": "cd /app && python3 -c "
import math,json
R=6371
def hav(a,b):
    lat1,lon1=a; lat2,lon2=b
    p1,p2=math.radians(lat1),math.radians(lat2)
    dp=p2-p1; dl=math.radians(lon2-lon1)
    x=math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(x))
speed=40.0; service=10
depot=(52.35614,4.94229)
orders={}
for line in open('/app/data/orders.csv').read().splitlines()[1:]:
    o=line.split(',')
    orders[o[0]]={'lat':float(o[1]),'lon':float(o[2]),'kg':int(o[3]),'ws':o[4],'we':o[5]}
del orders['C02']
def tomin(t):
    h,m=t.split(':'); return int(h)*60+int(m)
cap=780
ids=list(orders)
pts={id:(orders[id]['lat'],orders[id]['lon']) for id in ids}
def dist(a,b):
    if a==b: return 0
    return hav(a,b)
forbidden={frozenset(['C04','C01'])}
def evalroute(seq):
    t=8*60
    pos=depot
    dsum=0
    prev=None
    for id in seq:
        p=pts[id]
        if prev is not None and frozenset([prev,id]) in forbidden:
            return None
        d=dist(pos,p)
        dsum+=d
        t+=d/speed*60
        if t<tomin(orders[id]['ws']):
            t=tomin(orders[id]['ws'])
        if t>tomin(orders[id]['we']):
            return None
        t+=service
        pos=p
        prev=id
    dsum+=dist(pos,depot)
    return dsum, t
from itertools import combinations, permutations
allids=list(orders)
bestval=None; best=None
for size in range(0,len(allids)+1):
    for subset in combinations(allids,size):
        comp=tuple(x for x in allids if x not in subset)
        if not comp: continue
        bestsub=None
        for perm in permutations(subset):
            capsum=sum(orders[i]['kg'] for i in perm)
            if capsum>cap: continue
            r=evalroute(list(perm))
            if r is None: continue
            d,t=r
            if bestsub is None or d<bestsub[0]:
                bestsub=(d,perm,t)
        bestcomp=None
        for perm in permutations(comp):
            capsum=sum(orders[i]['kg'] for i in perm)
            if capsum>cap: continue
            r=evalroute(list(perm))
            if r is None: continue
            d,t=r
            if bestcomp is None or d<bestcomp[0]:
                bestcomp=(d,perm,t)
        if bestsub and bestcomp:
            total=bestsub[0]+bestcomp[0]
            if best is None or total<best[0]:
                best=(total, bestsub, bestcomp)
print('best total', best[0])
print('V1', best[1][1])
print('V2', best[2][1])
