import json, math, csv, itertools, os

R=6371.0
orders={}
with open('/app/data/orders.csv') as f:
    for r in csv.DictReader(f):
        o=r['order_id']
        orders[o]=dict(lat=float(r['lat']),lon=float(r['lon']),demand=float(r['demand_kg']),ws=r['window_start'],we=r['window_end'])

depot=json.load(open('/app/data/vans.json'))['depot']
D=(depot['lat'],depot['lon'])
speed=40.0
svc=10.0
del orders['C08']

pts={o:(orders[o]['lat'],orders[o]['lon']) for o in orders}

def toxy(lat,lon):
    la=math.radians(lat); lo=math.radians(lon)
    return (math.cos(la)*math.cos(lo), math.cos(la)*math.sin(lo), math.sin(la))

def dist(a,b):
    A=toxy(a[0],a[1]); B=toxy(b[0],b[1])
    d=math.acos(max(-1,min(1,A[0]*B[0]+A[1]*B[1]+A[2]*B[2])))
    return d*R

def tmin(t):
    h,m=t.split(':'); return int(h)*60+int(m)

def feasible(seq):
    t=8*60; prev=D
    for o in seq:
        t += dist(prev,pts[o])/speed*60
        if t<tmin(orders[o]['ws']): t=tmin(orders[o]['ws'])
        if t>tmin(orders[o]['we']): return False
        t += svc; prev=pts[o]
    t += dist(prev,D)/speed*60
    return True

def ok13(seq):
    if 'C01' in seq and 'C03' in seq:
        for i in range(len(seq)-1):
            if {seq[i],seq[i+1]}=={'C01','C03'}: return False
    return True

def seqdist(seq):
    p=[D]+[pts[o] for o in seq]+[D]
    return sum(dist(p[i],p[i+1]) for i in range(len(p)-1))

def best_seq(seq_set):
    best=None
    for perm in itertools.permutations(seq_set):
        if not ok13(perm): continue
        if not feasible(perm): continue
        d=seqdist(perm)
        if best is None or d<best[0]: best=(d,list(perm))
    return best

other=[o for o in orders if o!='C09']
best_total=None; best_routes=None
for mask in range(2**len(other)):
    v2=[other[i] for i in range(len(other)) if mask>>i&1]
    v1=[o for o in other if o not in v2]+['C09']
    if sum(orders[o]['demand'] for o in v1)>860: continue
    if sum(orders[o]['demand'] for o in v2)>860: continue
    b1=best_seq(v1); b2=best_seq(v2)
    if b1 is None or b2 is None: continue
    tot=b1[0]+b2[0]
    if best_total is None or tot<best_total:
        best_total=tot; best_routes=(b1[1],b2[1])

print("total",best_total)
print("V1",best_routes[0])
print("V2",best_routes[1])
os.makedirs('/app/output',exist_ok=True)
json.dump({"routes":{"V1":best_routes[0],"V2":best_routes[1]},"total_km":round(best_total,2)},open('/app/output/plan.json','w'))
print("written")
